import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Torso (main body) placed at starting position (x=10, y=2.0)
    torso = sandbox.add_beam(x=10.0, y=2.0, width=2.0, height=0.5, density=10.0)
    sandbox.set_material_properties(torso, restitution=0.1, friction=0.5)

    # Add four wheels closer to the torso for better stability and torque efficiency
    wheel_radius = 0.8
    wheel_y = 1.0 + wheel_radius  # Ensure wheels are in contact with ground (y=1.0)
    joints = []

    # Position wheels at x=9.5, 10.5, 9.0, 11.0 to minimize moment arm
    for i in range(4):
        if i == 0:
            x = 9.5
        elif i == 1:
            x = 10.5
        elif i == 2:
            x = 9.0
        else:  # i == 3
            x = 11.0
        wheel = sandbox.add_wheel(x, wheel_y, radius=wheel_radius, density=10.0)
        sandbox.set_material_properties(wheel, restitution=0.1, friction=1.0)
        pivot = sandbox.add_joint(torso, wheel, (x, wheel_y), type='pivot')
        joints.append(pivot)

    return {"body": torso, "joints": joints}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None

    # Adjust motor speed to avoid joint angle limit violations
    if torso is not None and torso.position.x > 24.0:
        rotation_speed = 0.0
    else:
        rotation_speed = -1.0  # Reduced speed to stay within joint limits

    # Use maximum torque to overcome low friction environment
    for j in joints:
        sandbox.set_motor(j, rotation_speed, max_torque=2000.0)
